export const WEEKDAY_LETTERS = ["M", "T", "W", "T", "F", "S", "S"]

const pad = (n: number) => String(n).padStart(2, "0")

export function startOfDay(d: Date): Date {
  return new Date(d.getFullYear(), d.getMonth(), d.getDate())
}

export function addDays(d: Date, n: number): Date {
  return new Date(d.getFullYear(), d.getMonth(), d.getDate() + n, d.getHours(), d.getMinutes())
}

export function startOfMonth(d: Date): Date {
  return new Date(d.getFullYear(), d.getMonth(), 1)
}

/** Same day-of-month `n` months away, clamped to the target month's last day. */
export function addMonths(d: Date, n: number): Date {
  const first = new Date(d.getFullYear(), d.getMonth() + n, 1)
  const last = new Date(first.getFullYear(), first.getMonth() + 1, 0).getDate()
  return new Date(first.getFullYear(), first.getMonth(), Math.min(d.getDate(), last))
}

export function dayKey(d: Date): string {
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`
}

export function isSameDay(a: Date, b: Date): boolean {
  return dayKey(a) === dayKey(b)
}

export function isSameMonth(a: Date, b: Date): boolean {
  return a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth()
}

/** Six Monday-first weeks (42 days) covering `month`. */
export function monthDays(month: Date): Date[] {
  const first = startOfMonth(month)
  const offset = (first.getDay() + 6) % 7
  return Array.from({ length: 42 }, (_, i) =>
    new Date(first.getFullYear(), first.getMonth(), 1 - offset + i)
  )
}

export function formatTime(d: Date): string {
  return `${pad(d.getHours())}:${pad(d.getMinutes())}`
}

export function formatMonth(d: Date): string {
  return d.toLocaleDateString(undefined, { month: "long", year: "numeric" })
}

export function formatDayLong(d: Date): string {
  return d.toLocaleDateString(undefined, { weekday: "long", month: "long", day: "numeric", year: "numeric" })
}

export function formatDayShort(d: Date): string {
  return d.toLocaleDateString(undefined, { weekday: "short", month: "short", day: "numeric" })
}

/** All-day means local midnight with no end, or an end at or past the next midnight. */
export function isAllDay(start: Date, end: Date | undefined): boolean {
  if (start.getHours() !== 0 || start.getMinutes() !== 0) return false
  return !end || end.getTime() >= addDays(startOfDay(start), 1).getTime()
}

/** Date header such as "TODAY 10/22", "TOMORROW 10/23" or "FRI 10/24". */
export function formatHeader(d: Date, now: Date): string {
  const md = `${d.getMonth() + 1}/${d.getDate()}`
  const diff = Math.round((startOfDay(d).getTime() - startOfDay(now).getTime()) / 86_400_000)
  if (diff === 0) return `TODAY ${md}`
  if (diff === 1) return `TOMORROW ${md}`
  return `${d.toLocaleDateString(undefined, { weekday: "short" }).toUpperCase()} ${md}`
}

import { useMemo, useState } from "react"

import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group"
import { useCollection } from "@/lib/mini/store"

import { MiniFull } from "./index"

type DemoTag = "home" | "work" | "health"

type DemoEvent = {
  id: string
  title: string
  start: string
  end?: string
  allDay: boolean
  tag?: DemoTag
}

type Preview = "live" | "empty" | "loading" | "error"

const TAGS: DemoTag[] = ["home", "work", "health"]

function at(dayOffset: number, time?: string, minutes = 30): Omit<DemoEvent, "id" | "title" | "tag"> {
  const base = new Date()
  const day = new Date(base.getFullYear(), base.getMonth(), base.getDate() + dayOffset)
  if (!time) return { start: day.toISOString(), allDay: true }
  const [h, m] = time.split(":").map(Number)
  const start = new Date(day.getFullYear(), day.getMonth(), day.getDate(), h, m)
  return {
    start: start.toISOString(),
    end: new Date(start.getTime() + minutes * 60_000).toISOString(),
    allDay: false,
  }
}

function makeSeed(): DemoEvent[] {
  return [
    { id: "seed-1", title: "Pick up dry cleaning", tag: "home", ...at(-2, "17:00") },
    { id: "seed-2", title: "Standup", tag: "work", ...at(0, "09:00") },
    { id: "seed-3", title: "Dentist", tag: "health", ...at(0, "14:00", 60) },
    { id: "seed-4", title: "Water the plants", tag: "home", ...at(0) },
    { id: "seed-5", title: "Lunch with Sam", ...at(1, "12:00", 60) },
    { id: "seed-6", title: "Call landlord", tag: "home", ...at(1, "16:30") },
    {
      id: "seed-7",
      title: "Renew the annual parking permit at the city office before the late fee applies",
      ...at(2, "10:00", 45),
    },
    { id: "seed-8", title: "Yoga", tag: "health", ...at(4, "18:30", 90) },
    { id: "seed-9", title: "Pay quarterly taxes", tag: "work", ...at(8) },
    { id: "seed-10", title: "Quarterly planning", tag: "work", ...at(12, "09:30", 60) },
    { id: "seed-11", title: "Car service", tag: "home", ...at(19, "15:00", 120) },
    { id: "seed-12", title: "Renew passport", ...at(27) },
  ]
}

const PREVIEWS: { value: Preview; label: string }[] = [
  { value: "live", label: "Live" },
  { value: "empty", label: "Empty" },
  { value: "loading", label: "Loading" },
  { value: "error", label: "Error" },
]

export default function Demo() {
  const seed = useMemo(() => makeSeed(), [])
  const events = useCollection<DemoEvent>("mini-full-demo", seed)
  const [preview, setPreview] = useState<Preview>("live")

  const status = preview === "loading" ? "loading" : preview === "error" ? "error" : events.status
  const items = preview === "empty" ? [] : events.items

  return (
    <div className="flex h-full min-h-[40rem] flex-col">
      <div className="flex shrink-0 items-center gap-2 border-b px-3 py-2 text-xs">
        <span className="text-muted-foreground">Preview state</span>
        <ToggleGroup
          type="multiple"
          variant="outline"
          size="sm"
          value={[preview]}
          onValueChange={(next) => {
            const picked = next.find((v) => v !== preview)
            if (picked) setPreview(picked as Preview)
          }}
          aria-label="Preview state"
          rovingFocus={false}
        >
          {PREVIEWS.map(({ value, label }) => (
            <ToggleGroupItem key={value} value={value} aria-label={`${label} state`}>
              {label}
            </ToggleGroupItem>
          ))}
        </ToggleGroup>
      </div>
      <div className="min-h-0 flex-1 p-3">
        <MiniFull<DemoEvent>
          items={items}
          status={status}
          error={preview === "error" ? new Error("Could not read appointments from this browser.") : events.error}
          onRetry={() => setPreview("live")}
          getStart={(e) => new Date(e.start)}
          getEnd={(e) => (e.end && !e.allDay ? new Date(e.end) : undefined)}
          getTag={(e) => e.tag}
          tags={TAGS}
          emptyHint='Try "dentist tomorrow at 10-11" or "call landlord fri /home".'
          fromEntry={(entry) => ({
            title: entry.title,
            start: (entry.start ?? new Date()).toISOString(),
            end: entry.end?.toISOString(),
            allDay: entry.allDay,
            tag: TAGS.find((t) => t === entry.tag),
          })}
          onAdd={async (item) => {
            await events.add({ id: crypto.randomUUID(), ...item })
            if (preview === "empty") setPreview("live")
          }}
          onRemove={events.remove}
        />
      </div>
    </div>
  )
}

import { cn } from "@/lib/utils"

import {
  dayKey,
  formatDayLong,
  formatTime,
  isAllDay,
  isSameDay,
  isSameMonth,
  monthDays,
} from "./dates"

const WEEKDAYS = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"]

/**
 * Large month for the full view: one truncated line per item in each day cell,
 * at most three, with no overflow count. `previewDate` outlines the date the
 * quick-add text currently resolves to.
 */
export function FullMonth<T extends { id: string; title: string }>({
  month,
  selected,
  items,
  getStart,
  getEnd,
  selectedId,
  previewDate,
  today,
  onSelectDate,
  onSelectItem,
  onDoubleClickDate,
}: {
  month: Date
  selected: Date
  items: T[]
  getStart: (item: T) => Date | undefined
  getEnd?: (item: T) => Date | undefined
  selectedId?: string
  previewDate?: Date
  today: Date
  onSelectDate(d: Date): void
  onSelectItem(id: string): void
  onDoubleClickDate(d: Date): void
}) {
  const byDay = new Map<string, { item: T; start: Date }[]>()
  for (const item of items) {
    const start = getStart(item)
    if (!start) continue
    const key = dayKey(start)
    byDay.set(key, [...(byDay.get(key) ?? []), { item, start }])
  }
  for (const list of byDay.values()) list.sort((a, b) => a.start.getTime() - b.start.getTime())

  return (
    <div className="grid h-full min-h-0 grid-cols-7 grid-rows-[auto_repeat(6,minmax(0,1fr))] border-t border-l">
      {WEEKDAYS.map((name) => (
        <div key={name} className="border-r border-b px-2 py-1 text-xs text-muted-foreground">
          {name}
        </div>
      ))}
      {monthDays(month).map((day) => {
        const entries = byDay.get(dayKey(day)) ?? []
        const inMonth = isSameMonth(day, month)
        const isToday = isSameDay(day, today)
        const isSelected = isSameDay(day, selected)
        const isPreview = previewDate !== undefined && isSameDay(day, previewDate)
        return (
          <div
            key={dayKey(day)}
            className={cn(
              "flex min-h-0 flex-col gap-0.5 overflow-hidden border-r border-b p-1",
              !inMonth && "bg-muted/40 text-muted-foreground",
              isSelected && "bg-[var(--mini-accent-soft)]",
              isPreview && "outline-1 -outline-offset-1 outline-dashed outline-[var(--mini-accent)]"
            )}
          >
            <button
              type="button"
              aria-label={formatDayLong(day)}
              aria-pressed={isSelected}
              aria-current={isToday ? "date" : undefined}
              onClick={() => onSelectDate(day)}
              onDoubleClick={() => onDoubleClickDate(day)}
              className={cn(
                "flex size-6 shrink-0 items-center justify-center self-start rounded-full text-xs outline-none focus-visible:ring-2 focus-visible:ring-ring",
                isToday ? "bg-primary font-medium text-primary-foreground" : "hover:bg-accent"
              )}
            >
              {day.getDate()}
            </button>
            {entries.slice(0, 3).map(({ item, start }) => {
              const end = getEnd?.(item)
              return (
                <button
                  key={item.id}
                  type="button"
                  aria-current={item.id === selectedId ? "true" : undefined}
                  onClick={() => onSelectItem(item.id)}
                  className={cn(
                    "w-full shrink-0 truncate rounded px-1 text-left text-[0.7rem] leading-5 outline-none hover:bg-accent focus-visible:ring-2 focus-visible:ring-ring",
                    item.id === selectedId && "bg-accent font-medium"
                  )}
                >
                  {isAllDay(start, end) ? "" : `${formatTime(start)} `}
                  {item.title}
                </button>
              )
            })}
          </div>
        )
      })}
    </div>
  )
}

import { useEffect, useRef, useState, type ReactNode } from "react"
import { useHotkeys } from "react-hotkeys-hook"
import { toast } from "sonner"
import { ChevronLeftIcon, ChevronRightIcon } from "lucide-react"

import { EmptyState, ErrorState, LoadingState } from "@/components/mini/states"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Kbd } from "@/components/ui/kbd"
import { Separator } from "@/components/ui/separator"
import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group"
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip"
import { cn } from "@/lib/utils"

import {
  addDays,
  addMonths,
  dayKey,
  formatDayLong,
  formatMonth,
  isSameDay,
  startOfDay,
  startOfMonth,
} from "./dates"
import { FullMonth } from "./full-month"
import { MonthGrid } from "./month-grid"
import { parseEntry, withDefaultEnd, type ParsedEntry } from "./parse"
import { ParsePreview, QuickAdd } from "./quick-add"
import { UpcomingList } from "./upcoming-list"

export type MiniFullProps<T> = {
  items: T[]
  status: "loading" | "ready" | "error"
  error?: Error
  onRetry?: () => void
  getStart: (item: T) => Date | undefined
  getEnd?: (item: T) => Date | undefined
  getTag?: (item: T) => string | undefined
  fromEntry: (entry: ParsedEntry) => Omit<T, "id">
  onAdd: (item: Omit<T, "id">) => Promise<void>
  onRemove?: (id: string) => Promise<void>
  parse?: (text: string, now: Date) => ParsedEntry
  tags?: string[]
  renderRow?: (item: T, ctx: { selected: boolean; past: boolean }) => ReactNode
  mode?: "mini" | "full"
  onModeChange?: (mode: "mini" | "full") => void
  defaultDurationMinutes?: number
  emptyHint?: string
}

type View = "list" | "month"

function useNow(): Date {
  const [now, setNow] = useState(() => new Date())
  useEffect(() => {
    const timer = setInterval(() => setNow(new Date()), 60_000)
    return () => clearInterval(timer)
  }, [])
  return now
}

function message(cause: unknown): string {
  return cause instanceof Error ? cause.message : String(cause)
}

function IconButton({ label, onClick, children }: { label: string; onClick(): void; children: ReactNode }) {
  return (
    <Tooltip>
      <TooltipTrigger asChild>
        <Button variant="ghost" size="icon-sm" aria-label={label} onClick={onClick}>
          {children}
        </Button>
      </TooltipTrigger>
      <TooltipContent>{label}</TooltipContent>
    </Tooltip>
  )
}

/**
 * A quick-add panel (input, live parse card, month grid, upcoming list) that
 * expands into a full view of the same items. The app owns the data: pass
 * `items` and persist through `onAdd` / `onRemove`. A parsed entry with no date
 * lands all-day on the selected date. Dimmed means ended before now; an item
 * is all-day when it starts at local midnight with no end.
 */
export function MiniFull<T extends { id: string; title: string }>({
  items,
  status,
  error,
  onRetry,
  getStart,
  getEnd,
  getTag,
  fromEntry,
  onAdd,
  onRemove,
  parse,
  tags,
  renderRow,
  mode: modeProp,
  onModeChange,
  defaultDurationMinutes = 30,
  emptyHint,
}: MiniFullProps<T>) {
  const now = useNow()
  const today = startOfDay(now)
  const [text, setText] = useState("")
  const [selectedId, setSelectedId] = useState<string>()
  const [selectedDate, setSelectedDate] = useState(today)
  const [month, setMonth] = useState(() => startOfMonth(today))
  const [innerMode, setInnerMode] = useState<"mini" | "full">("mini")
  const [view, setView] = useState<View>("list")
  const [filter, setFilter] = useState("")
  const inputRef = useRef<HTMLInputElement>(null)
  const panelRef = useRef<HTMLElement>(null)
  const pendingFocus = useRef<string | null>(null)
  const submitting = useRef(false)

  const mode = modeProp ?? innerMode
  function setMode(next: "mini" | "full") {
    if (modeProp === undefined) setInnerMode(next)
    onModeChange?.(next)
  }

  const prevMode = useRef(mode)
  useEffect(() => {
    if (prevMode.current === "full" && mode === "mini") inputRef.current?.focus()
    prevMode.current = mode
  }, [mode])

  useEffect(() => {
    inputRef.current?.focus()
  }, [])

  useEffect(() => {
    if (pendingFocus.current === null || pendingFocus.current !== selectedId) return
    panelRef.current
      ?.querySelector<HTMLElement>(`[data-row-id="${CSS.escape(pendingFocus.current)}"]`)
      ?.focus()
    pendingFocus.current = null
  }, [selectedId])

  const ready = status === "ready"
  const parsed = text ? (parse ? parse(text, now) : parseEntry(text, now, tags)) : undefined
  const entry = withDefaultEnd(parsed ?? { title: "", allDay: true, matches: [] }, defaultDurationMinutes)

  const dated = (ready ? items : [])
    .flatMap((item) => {
      const start = getStart(item)
      return start ? [{ item, start }] : []
    })
    .sort((a, b) => a.start.getTime() - b.start.getTime())
  const marked = new Map<string, number>()
  for (const { start } of dated) marked.set(dayKey(start), (marked.get(dayKey(start)) ?? 0) + 1)
  const upcoming = dated.filter(({ start }) => start >= today).length
  const needle = filter.trim().toLowerCase()
  const matchesFilter = (item: T) => !needle || item.title.toLowerCase().includes(needle)
  const filtered = items.filter(matchesFilter)
  const visible = dated.filter(({ item }) => matchesFilter(item))
  const activeId = visible.some(({ item }) => item.id === selectedId) ? selectedId : undefined

  function selectDate(d: Date) {
    setSelectedDate(startOfDay(d))
    setMonth(startOfMonth(d))
    setSelectedId(undefined)
  }

  function selectItem(id: string) {
    setSelectedId(id)
    const item = items.find((i) => i.id === id)
    const start = item && getStart(item)
    if (start) {
      setSelectedDate(startOfDay(start))
      setMonth(startOfMonth(start))
    }
  }

  function openItem(id: string) {
    selectItem(id)
    setMode("full")
  }

  function topDateChanged(d: Date) {
    setSelectedDate(d)
    setMonth(startOfMonth(d))
    setSelectedId((id) => {
      const item = id ? items.find((i) => i.id === id) : undefined
      const start = item && getStart(item)
      return start && isSameDay(start, d) ? id : undefined
    })
  }

  async function submit() {
    if (!ready || submitting.current || !entry.title.trim()) return
    const submitted = text
    const filled: ParsedEntry = entry.start
      ? entry
      : { ...entry, start: startOfDay(selectedDate), allDay: true }
    submitting.current = true
    try {
      await onAdd(fromEntry(filled))
      setText((current) => (current === submitted ? "" : current))
      selectDate(filled.start!)
    } catch (cause) {
      toast.error(`Could not add "${filled.title}": ${message(cause)}`)
    } finally {
      submitting.current = false
      inputRef.current?.focus()
    }
  }

  async function removeSelected() {
    const index = visible.findIndex(({ item }) => item.id === activeId)
    if (index < 0 || !onRemove) return
    const { item } = visible[index]
    const neighbor = visible[index + 1] ?? visible[index - 1]
    try {
      await onRemove(item.id)
    } catch (cause) {
      toast.error(`Could not remove "${item.title}": ${message(cause)}`)
      return
    }
    const rest = Object.fromEntries(
      Object.entries(item).filter(([key]) => key !== "id")
    ) as Omit<T, "id">
    toast(`Removed "${item.title}"`, {
      action: {
        label: "Undo",
        onClick: () => {
          onAdd(rest).catch((cause) => toast.error(`Could not restore: ${message(cause)}`))
        },
      },
    })
    if (neighbor) {
      pendingFocus.current = neighbor.item.id
      selectItem(neighbor.item.id)
    } else {
      setSelectedId(undefined)
    }
  }

  function moveSelection(step: 1 | -1) {
    if (visible.length === 0) return
    const index = visible.findIndex(({ item }) => item.id === activeId)
    let next: number
    if (index >= 0) next = Math.min(Math.max(index + step, 0), visible.length - 1)
    else if (step === 1) next = Math.max(visible.findIndex(({ start }) => start >= selectedDate), 0)
    else next = visible.length - 1
    const id = visible[next].item.id
    pendingFocus.current = id
    if (id === activeId) {
      panelRef.current?.querySelector<HTMLElement>(`[data-row-id="${CSS.escape(id)}"]`)?.focus()
      return
    }
    selectItem(id)
  }

  function insertDate(d: Date) {
    const md = `${d.getMonth() + 1}/${d.getDate()}`
    const plain = parseEntry(md, now).start
    const token = plain && isSameDay(plain, d) ? md : `${md}/${d.getFullYear()}`
    selectDate(d)
    setText((current) => (current.trim() ? `${current.trim()} ${token} ` : `${token} `))
    requestAnimationFrame(() => {
      const input = inputRef.current
      input?.focus()
      input?.setSelectionRange(input.value.length, input.value.length)
    })
  }

  function step(direction: 1 | -1) {
    selectDate(view === "month" ? addMonths(selectedDate, direction) : addDays(selectedDate, direction))
  }

  const fullMonthView = mode === "full" && view === "month"
  useHotkeys("n", () => inputRef.current?.focus(), { preventDefault: true })
  useHotkeys("e", () => setMode(mode === "full" ? "mini" : "full"), { preventDefault: true })
  useHotkeys("t", () => selectDate(today), { preventDefault: true })
  useHotkeys("up", () => moveSelection(-1), { preventDefault: true })
  useHotkeys("down", () => moveSelection(1), { preventDefault: true })
  useHotkeys("left", () => selectDate(addMonths(selectedDate, -1)), {
    preventDefault: true,
    enabled: fullMonthView,
  })
  useHotkeys("right", () => selectDate(addMonths(selectedDate, 1)), {
    preventDefault: true,
    enabled: fullMonthView,
  })
  useHotkeys("backspace,delete", () => void removeSelected(), {
    preventDefault: true,
    enabled: activeId !== undefined && onRemove !== undefined,
  })

  function listRegion(className?: string): ReactNode {
    if (status === "loading") return <LoadingState label="Loading items" />
    if (status === "error") {
      return <ErrorState error={error ?? new Error("Could not load items")} onRetry={onRetry} />
    }
    if (items.length === 0) {
      return (
        <EmptyState
          title="Nothing here yet"
          description={emptyHint ?? 'Type something like "dentist tomorrow 10-11" and press Enter.'}
        />
      )
    }
    return (
      <UpcomingList
        className={className}
        items={filtered}
        getStart={getStart}
        getEnd={getEnd}
        getTag={getTag}
        renderRow={renderRow}
        selectedId={activeId}
        selectedDate={selectedDate}
        today={now}
        onSelect={selectItem}
        onOpen={openItem}
        onTopDateChange={topDateChanged}
      />
    )
  }

  const panel = (
    <div className="flex h-full min-h-0 flex-col gap-2 p-2">
      <QuickAdd
        value={text}
        onChange={setText}
        onSubmit={() => void submit()}
        entry={entry}
        disabled={!ready}
        tags={tags}
        inputRef={inputRef}
      />
      {text ? (
        <ParsePreview entry={entry} onSubmit={() => void submit()} disabled={!ready} />
      ) : (
        <div className="shrink-0">
          <div className="mb-1 flex items-center justify-between pl-1">
            <span className="text-sm font-medium">{formatMonth(month)}</span>
            <div className="flex">
              <IconButton label="Previous month" onClick={() => setMonth(addMonths(month, -1))}>
                <ChevronLeftIcon />
              </IconButton>
              <IconButton label="Next month" onClick={() => setMonth(addMonths(month, 1))}>
                <ChevronRightIcon />
              </IconButton>
            </div>
          </div>
          <MonthGrid
            month={month}
            selected={selectedDate}
            marked={marked}
            today={now}
            onSelectDate={selectDate}
            onDoubleClickDate={insertDate}
          />
        </div>
      )}
      <Separator />
      <div className="-mx-1 flex min-h-0 flex-1 flex-col">{listRegion()}</div>
      <Separator />
      <div className="flex shrink-0 items-center justify-between gap-2">
        <Button
          variant="ghost"
          size="sm"
          onMouseDown={(e) => e.preventDefault()}
          onClick={() => setMode(mode === "full" ? "mini" : "full")}
        >
          {mode === "full" ? "Collapse" : "Expand"}
          <Kbd>e</Kbd>
        </Button>
        <span className="text-xs text-muted-foreground tabular-nums">{upcoming} upcoming</span>
