import { addDays, startOfDay } from "./dates"

export type ParsedEntry = {
  title: string
  start?: Date
  end?: Date
  allDay: boolean
  tag?: string
  matches: { field: "when" | "tag"; from: number; to: number }[]
}

const WEEKDAYS: [RegExp, number][] = [
  [/^sun/, 0],
  [/^mon/, 1],
  [/^tue/, 2],
  [/^wed/, 3],
  [/^thu/, 4],
  [/^fri/, 5],
  [/^sat/, 6],
]

const TAG = /(?<=^|\s)\/([a-z][\w-]*)/gi
const TIME_RANGE =
  /(?<![\w:/])(?:at\s+)?(\d{1,2})(?::(\d{2}))?\s*(am|pm)?\s*[-–]\s*(\d{1,2})(?::(\d{2}))?\s*(am|pm)?(?![\w:/])/i
const TIME_AT = /(?<![\w:/])at\s+(\d{1,2})(?::(\d{2}))?\s*(am|pm)?(?![\w:/])/i
const TIME_MERIDIEM = /(?<![\w:/])(\d{1,2})(?::(\d{2}))?\s*(am|pm)(?![\w:/])/i
const DATE_MD = /(?<![\w/])(?:on\s+)?(\d{1,2})\/(\d{1,2})(?:\/(\d{4}|\d{2}))?(?![\w/])/i
const DATE_WORD =
  /(?<!\w)(?:on\s+|next\s+)?(today|tomorrow|tmrw|sunday|sun|monday|mon|tuesday|tues|tue|wednesday|wed|thursday|thurs|thur|thu|friday|fri|saturday|sat)(?!\w)/i

type Range = { from: number; to: number }

function hourOf(h: number, meridiem: string | undefined): number | undefined {
  if (h > 23) return undefined
  const m = meridiem?.toLowerCase()
  if (m) {
    if (h < 1 || h > 12) return undefined
    return (h % 12) + (m === "pm" ? 12 : 0)
  }
  // a bare 1-6 reads as afternoon ("3-4"), 7-12 as morning
  return h >= 1 && h <= 6 ? h + 12 : h
}

/**
 * Places an end time that reads at or before its start: first as the same day's
 * afternoon ("9-8"), else as the next morning ("11pm-1am") when that is under
 * 12 hours. Minutes past 24h land on the following day. Undefined when neither fits.
 */
function resolveEarlierEnd(start: number, end: number): number | undefined {
  const sameDay = end + 12 * 60
  if (sameDay > start && sameDay <= 24 * 60) return sameDay
  const nextDay = end + 24 * 60
  if (end < start && nextDay - start <= 12 * 60) return nextDay
  return undefined
}

function claim(masked: string, range: Range): string {
  return masked.slice(0, range.from) + "\u0001".repeat(range.to - range.from) + masked.slice(range.to)
}

function rangeOf(m: RegExpExecArray): Range {
  return { from: m.index, to: m.index + m[0].length }
}

/**
 * Reads a date, a time or time range, and a `/tag` out of free text. Text in
 * double quotes is never parsed. A time without a date means today; neither
 * means `start` is undefined. `end` is only set when the text gives one.
 */
export function parseEntry(text: string, now: Date = new Date(), tags?: string[]): ParsedEntry {
  let work = text.replace(/"[^"]*"/g, (q) => "\u0000".repeat(q.length))
  const matches: ParsedEntry["matches"] = []
  const claimed: Range[] = []
  const take = (range: Range, field: "when" | "tag") => {
    claimed.push(range)
    matches.push({ field, ...range })
    work = claim(work, range)
  }

  let tag: string | undefined
  for (const m of work.matchAll(TAG)) {
    const name = m[1].toLowerCase()
    if (tags && tags.length > 0 && !tags.some((t) => t.toLowerCase() === name)) continue
    tag = tags?.find((t) => t.toLowerCase() === name) ?? name
    take(rangeOf(m), "tag")
    break
  }

  let minutes: { start: number; end?: number } | undefined
  const range = TIME_RANGE.exec(work)
  if (range) {
    const m1 = Number(range[2] ?? 0)
    const m2 = Number(range[5] ?? 0)
    const h2 = hourOf(Number(range[4]), range[6] ?? range[3])
    let h1 = hourOf(Number(range[1]), range[3] ?? range[6])
    if (!range[3] && range[6] && h1 !== undefined && h2 !== undefined && h1 * 60 + m1 > h2 * 60 + m2) {
      // "11-1pm" shares the end meridiem only when that keeps the start before the end
      h1 = hourOf(Number(range[1]), range[6].toLowerCase() === "pm" ? "am" : "pm")
    }
    if (h1 !== undefined && h2 !== undefined && m1 < 60 && m2 < 60) {
      const start = h1 * 60 + m1
      let end: number | undefined = h2 * 60 + m2
      if (end <= start) end = resolveEarlierEnd(start, end)
      minutes = { start, end }
      take(rangeOf(range), "when")
    }
  }
  if (!minutes) {
    const single = TIME_AT.exec(work) ?? TIME_MERIDIEM.exec(work)
    if (single) {
      const h = hourOf(Number(single[1]), single[3])
      const min = Number(single[2] ?? 0)
      if (h !== undefined && min < 60) {
        minutes = { start: h * 60 + min }
        take(rangeOf(single), "when")
      }
    }
  }

  const today = startOfDay(now)
  let day: Date | undefined
  const md = DATE_MD.exec(work)
  if (md) {
    const month = Number(md[1])
    const date = Number(md[2])
    let year = today.getFullYear()
    if (md[3]) year = md[3].length === 2 ? 2000 + Number(md[3]) : Number(md[3])
    let candidate = new Date(year, month - 1, date)
    const valid = (d: Date) => d.getMonth() === month - 1 && d.getDate() === date
    if (valid(candidate)) {
      if (!md[3] && candidate < today) candidate = new Date(year + 1, month - 1, date)
      if (valid(candidate)) {
        day = candidate
        take(rangeOf(md), "when")
      }
    }
  }
  if (!day) {
    const word = DATE_WORD.exec(work)
    if (word) {
      const w = word[1].toLowerCase()
      if (w === "today") day = today
      else if (w === "tomorrow" || w === "tmrw") day = addDays(today, 1)
      else {
        const target = WEEKDAYS.find(([re]) => re.test(w))![1]
        day = addDays(today, ((target - today.getDay() + 6) % 7) + 1)
      }
      take(rangeOf(word), "when")
    }
  }

  if (!day && minutes) day = today

  const title = text
    .split("")
    .map((ch, i) => (claimed.some((r) => i >= r.from && i < r.to) ? " " : ch))
    .join("")
    .replace(/"/g, "")
    .replace(/\s+/g, " ")
    .trim()

  if (!day) return { title, allDay: true, tag, matches }
  if (!minutes) return { title, start: day, allDay: true, tag, matches }

  const at = (m: number) => new Date(day.getFullYear(), day.getMonth(), day.getDate(), 0, m)
  return {
    title,
    start: at(minutes.start),
    end: minutes.end === undefined ? undefined : at(minutes.end),
    allDay: false,
    tag,
    matches,
  }
}

/** Fills the default length for a timed entry that gave a start and no end. */
export function withDefaultEnd(entry: ParsedEntry, minutes: number): ParsedEntry {
  if (entry.allDay || !entry.start || entry.end) return entry
  return { ...entry, end: new Date(entry.start.getTime() + minutes * 60_000) }
}

import { useEffect, useRef, useState, type KeyboardEvent, type RefObject } from "react"
import { CornerDownLeftIcon } from "lucide-react"

import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Card, CardContent } from "@/components/ui/card"
import { Input } from "@/components/ui/input"
import { cn } from "@/lib/utils"

import { formatDayShort, formatTime } from "./dates"
import type { ParsedEntry } from "./parse"

const TAG_TOKEN = /(?:^|\s)\/([\w-]*)$/

/**
 * The always-visible input row. Enter submits when the title is non-empty and
 * `disabled` is false; Esc clears the text, then blurs; typing `/` offers `tags`.
 */
export function QuickAdd({
  value,
  onChange,
  onSubmit,
  entry,
  disabled,
  tags = [],
  inputRef,
}: {
  value: string
  onChange(v: string): void
  onSubmit(): void
  entry: ParsedEntry
  disabled?: boolean
  tags?: string[]
  inputRef?: RefObject<HTMLInputElement | null>
}) {
  const [caret, setCaret] = useState(0)
  const [active, setActive] = useState(0)
  const [dismissedAt, setDismissedAt] = useState<string | null>(null)
  const pendingCaret = useRef<number | null>(null)
  const fallbackRef = useRef<HTMLInputElement | null>(null)
  const ref = inputRef ?? fallbackRef

  const before = value.slice(0, caret)
  const token = TAG_TOKEN.exec(before)
  const query = token?.[1].toLowerCase() ?? ""
  const options = token ? tags.filter((t) => t.toLowerCase().startsWith(query)) : []
  const exact = options.length === 1 && options[0].toLowerCase() === query
  const open = token !== null && options.length > 0 && !exact && dismissedAt !== value
  const activeIndex = Math.min(active, Math.max(options.length - 1, 0))

  useEffect(() => {
    if (pendingCaret.current === null) return
    ref.current?.setSelectionRange(pendingCaret.current, pendingCaret.current)
    pendingCaret.current = null
  }, [value, ref])

  function pick(tag: string) {
    if (!token) return
    const start = before.length - token[0].replace(/^\s/, "").length
    const next = `${value.slice(0, start)}/${tag} ${value.slice(caret)}`
    pendingCaret.current = start + tag.length + 2
    setCaret(pendingCaret.current)
    onChange(next)
  }

  function onKeyDown(e: KeyboardEvent<HTMLInputElement>) {
    if (e.nativeEvent.isComposing) return
    if (open) {
      if (e.key === "ArrowDown" || e.key === "ArrowUp") {
        e.preventDefault()
        const step = e.key === "ArrowDown" ? 1 : -1
        setActive((activeIndex + step + options.length) % options.length)
        return
      }
      if (e.key === "Enter" || e.key === "Tab") {
        e.preventDefault()
        pick(options[activeIndex])
        return
      }
      if (e.key === "Escape") {
        e.preventDefault()
        setDismissedAt(value)
        return
      }
    }
    if (e.key === "Enter") {
      e.preventDefault()
      if (!disabled && entry.title.trim()) onSubmit()
    } else if (e.key === "Escape") {
      e.preventDefault()
      if (value) onChange("")
      else e.currentTarget.blur()
    }
  }

  return (
    <div className="relative">
      <Input
        ref={ref}
        value={value}
        placeholder="Add: dentist tomorrow 10-11"
        aria-label="Quick add"
        role="combobox"
        aria-expanded={open}
        aria-controls="mini-full-tags"
        aria-autocomplete="list"
        aria-activedescendant={open ? `mini-full-tag-${activeIndex}` : undefined}
        autoComplete="off"
        spellCheck={false}
        onChange={(e) => {
          setCaret(e.target.selectionStart ?? e.target.value.length)
          setActive(0)
          onChange(e.target.value)
        }}
        onSelect={(e) => setCaret(e.currentTarget.selectionStart ?? 0)}
        onKeyDown={onKeyDown}
      />
      {open ? (
        <ul
          id="mini-full-tags"
          role="listbox"
          aria-label="Tags"
          className="absolute inset-x-0 top-full z-20 mt-1 rounded-md border bg-popover p-1 text-popover-foreground shadow-md"
        >
          {options.map((tag, i) => (
            <li
              key={tag}
              id={`mini-full-tag-${i}`}
              role="option"
              aria-selected={i === activeIndex}
              className={cn(
                "cursor-pointer rounded-sm px-2 py-1 text-xs",
                i === activeIndex && "bg-accent text-accent-foreground"
              )}
              onMouseDown={(e) => e.preventDefault()}
              onClick={() => pick(tag)}
            >
              /{tag}
            </li>
          ))}
        </ul>
      ) : null}
    </div>
  )
}

function whenText(entry: ParsedEntry): string {
  if (!entry.start) return "None"
  const day = formatDayShort(entry.start)
  if (entry.allDay) return day
  const end = entry.end ? `–${formatTime(entry.end)}` : ""
  return `${day}, ${formatTime(entry.start)}${end}`
}

/** Live card for the text being typed: title, when, all-day, tag and an Add button. */
export function ParsePreview({
  entry,
  onSubmit,
  disabled,
}: {
  entry: ParsedEntry
  onSubmit(): void
  disabled?: boolean
}) {
  const values = {
    when: whenText(entry),
    allDay: entry.start ? (entry.allDay ? "Yes" : "No") : "None",
    tag: entry.tag ?? "None",
  }
  const [shown, setShown] = useState(values)
  const [flash, setFlash] = useState<Partial<Record<keyof typeof values, boolean>>>({})

  if (shown.when !== values.when || shown.allDay !== values.allDay || shown.tag !== values.tag) {
    setShown(values)
    setFlash({
      when: shown.when !== values.when,
      allDay: shown.allDay !== values.allDay,
      tag: shown.tag !== values.tag,
    })
  }

  useEffect(() => {
    if (!Object.values(flash).some(Boolean)) return
    const timer = setTimeout(() => setFlash({}), 700)
    return () => clearTimeout(timer)
  }, [flash])

  const cell = (key: keyof typeof values) =>
    cn(
      "-mx-1 min-w-0 rounded px-1 transition-colors duration-500",
      flash[key] && "bg-[var(--mini-accent-soft)] motion-reduce:bg-transparent"
    )

  return (
    <Card size="sm" role="group" data-mini="surface" aria-label="Parsed entry" className="rounded-md">
      <CardContent className="flex flex-col gap-2">
        <dl className="grid grid-cols-[4.5rem_minmax(0,1fr)] items-baseline gap-x-2 gap-y-1 text-xs">
          <dt className="text-muted-foreground">Title</dt>
          <dd className="line-clamp-2 min-w-0 text-sm font-medium break-words">
            {entry.title || <span className="text-muted-foreground">None</span>}
          </dd>
          <dt className="text-muted-foreground">When</dt>
          <dd className={cell("when")}>{values.when}</dd>
          <dt className="text-muted-foreground">All-day</dt>
          <dd className={cell("allDay")}>{values.allDay}</dd>
          <dt className="text-muted-foreground">Tag</dt>
          <dd className={cell("tag")}>
            {entry.tag ? <Badge variant="outline">{entry.tag}</Badge> : values.tag}
          </dd>
        </dl>
        <Button
          size="sm"
          className="w-full"
          disabled={disabled || !entry.title.trim()}
          onClick={onSubmit}
        >
          Add
          <CornerDownLeftIcon aria-hidden />
        </Button>
      </CardContent>
    </Card>
  )
}

import { useEffect, useRef, type ReactNode } from "react"

import { cn } from "@/lib/utils"

import { addDays, dayKey, formatHeader, formatTime, isAllDay, startOfDay } from "./dates"

export type RowContext = { selected: boolean; past: boolean }

type Group<T> = { key: string; date: Date; items: T[] }

function timeLabel(start: Date, end: Date | undefined): string {
  if (isAllDay(start, end)) return "All-day"
  return end ? `${formatTime(start)}-${formatTime(end)}` : formatTime(start)
}

/**
 * Items in time order under date headers; past items are dimmed. A row is a
 * button: click selects, double-click or Enter opens. When `selectedDate`
 * changes the list scrolls to that date's header, and when the user scrolls it
 * reports the topmost header through `onTopDateChange`.
 */
export function UpcomingList<T extends { id: string; title: string }>({
  items,
  getStart,
  getEnd,
  getTag,
  selectedId,
  selectedDate,
  onSelect,
  onOpen,
  onTopDateChange,
  renderRow,
  today = new Date(),
  className,
}: {
  items: T[]
  getStart: (item: T) => Date | undefined
  getEnd?: (item: T) => Date | undefined
  getTag?: (item: T) => string | undefined
  selectedId?: string
  selectedDate?: Date
  onSelect(id: string): void
  onOpen(id: string): void
  onTopDateChange?(d: Date): void
  renderRow?: (item: T, ctx: RowContext) => ReactNode
  today?: Date
  className?: string
}) {
  const rootRef = useRef<HTMLDivElement>(null)
  const lastUserInput = useRef(-Infinity)
  const pointerHeld = useRef(false)
  const lastReported = useRef<string | null>(null)
  const todayKey = dayKey(today)
  const selectedKey = selectedDate ? dayKey(selectedDate) : undefined

  const groups = (() => {
    const dated = items
      .map((item) => ({ item, start: getStart(item) }))
      .filter((x): x is { item: T; start: Date } => x.start !== undefined)
      .sort((a, b) => a.start.getTime() - b.start.getTime())
    const byDay = new Map<string, Group<T>>()
    for (const { item, start } of dated) {
      const key = dayKey(start)
      const group = byDay.get(key) ?? { key, date: startOfDay(start), items: [] }
      group.items.push(item)
      byDay.set(key, group)
    }
    if (byDay.size > 0 && !byDay.has(todayKey)) {
      byDay.set(todayKey, { key: todayKey, date: startOfDay(today), items: [] })
    }
    return [...byDay.values()].sort((a, b) => a.key.localeCompare(b.key))
  })()
  const signature = groups.map((g) => `${g.key}:${g.items.map((i) => i.id).join(",")}`).join("|")

  useEffect(() => {
    const root = rootRef.current
    if (!root) return
    if (selectedKey !== undefined && lastReported.current === selectedKey) {
      lastReported.current = null
      return
    }
    const row = selectedId
      ? root.querySelector<HTMLElement>(`[data-row-id="${CSS.escape(selectedId)}"]`)
      : null
    if (row) {
      row.scrollIntoView({ block: "nearest" })
      return
    }
    if (selectedKey === undefined) return
    const sections = [...root.querySelectorAll<HTMLElement>("[data-date]")]
    const header = sections.find((s) => s.dataset.date! >= selectedKey) ?? sections.at(-1)
    if (header) {
      root.scrollTop += header.getBoundingClientRect().top - root.getBoundingClientRect().top
    }
  }, [selectedKey, selectedId, signature])

  useEffect(() => {
    const release = () => {
      if (pointerHeld.current) lastUserInput.current = performance.now()
      pointerHeld.current = false
    }
    window.addEventListener("pointerup", release)
    return () => window.removeEventListener("pointerup", release)
  }, [])

  const noteUserInput = () => {
    lastUserInput.current = performance.now()
  }

  function onScroll() {
    const root = rootRef.current
    // layout shifts and programmatic scrolls also fire scroll events; only react to the user's own
    if (!root || !onTopDateChange) return
    if (!pointerHeld.current && performance.now() - lastUserInput.current > 300) return
    const top = root.getBoundingClientRect().top
    const sections = root.querySelectorAll<HTMLElement>("[data-date]")
    for (const section of sections) {
      if (section.getBoundingClientRect().bottom > top + 1) {
        const key = section.dataset.date!
        if (key !== selectedKey) {
          lastReported.current = key
          const [y, m, d] = key.split("-").map(Number)
          onTopDateChange(new Date(y, m - 1, d))
        }
        return
      }
    }
  }

  const now = today.getTime()

  return (
    <div
      ref={rootRef}
      onScroll={onScroll}
      onWheel={noteUserInput}
      onTouchMove={noteUserInput}
      onPointerDown={(e) => {
        // a press on the scroller itself is a scrollbar drag; presses on rows are not scrolling
        if (e.target === e.currentTarget) pointerHeld.current = true
      }}
      className={cn("min-h-0 flex-1 overflow-y-auto", className)}
    >
      {groups.map((group) => (
        <section key={group.key} data-date={group.key} aria-label={formatHeader(group.date, today)}>
          <h3
            data-mini="group-header"
            className={cn(
              "px-2 pt-2 pb-1 text-[0.65rem] font-medium tracking-wide text-muted-foreground",
              group.key < todayKey && "opacity-60"
            )}
          >
            {formatHeader(group.date, today)}
          </h3>
          {group.items.length === 0 ? (
            <p className="px-2 py-1 text-xs text-[var(--mini-accent)]">No items today</p>
          ) : (
            <ul>
              {group.items.map((item) => {
                const start = getStart(item)!
                const end = getEnd?.(item)
                const selected = item.id === selectedId
                const past = (end ?? (isAllDay(start, end) ? addDays(group.date, 1) : start)).getTime() < now
                const tag = getTag?.(item)
                return (
                  <li key={item.id}>
                    <button
                      type="button"
                      data-row-id={item.id}
                      data-mini="row"
                      aria-current={selected ? "true" : undefined}
                      onClick={() => onSelect(item.id)}
                      onDoubleClick={() => onOpen(item.id)}
                      onKeyDown={(e) => {
                        if (e.key === "Enter") {
                          e.preventDefault()
                          onOpen(item.id)
                        }
                      }}
                      className={cn(
                        "flex w-full items-center gap-2 rounded-md px-2 text-left text-xs outline-none focus-visible:ring-2 focus-visible:ring-ring",
                        "h-[var(--mini-row-height)] hover:bg-accent",
                        selected && "bg-accent text-accent-foreground",
                        past && "opacity-60"
                      )}
                    >
                      {renderRow ? (
                        renderRow(item, { selected, past })
                      ) : (
                        <>
                          <span aria-hidden className="size-1.5 shrink-0 rounded-full bg-[var(--mini-accent)]" />
                          <span className="w-[6.25rem] shrink-0 text-muted-foreground tabular-nums">
                            {timeLabel(start, end)}
                          </span>
                          <span className="min-w-0 flex-1 truncate">{item.title}</span>
                          {tag ? <span className="shrink-0 text-muted-foreground">{tag}</span> : null}
                        </>
                      )}
                    </button>
                  </li>
                )
              })}
            </ul>
          )}
        </section>
      ))}
    </div>
  )
}
